package source

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"sync"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Registry is the set of source kinds harnaas can resolve, keyed by the name a
// manifest writes.
//
// It exists so that adding a kind is additive: the install flow asks the
// registry for a resolver and hands it a request, and contains no branch on
// which kind it got. A registry value rather than one package-level map is what
// lets a test exercise dispatch — including the failure for a kind nobody
// registered — without reaching into the set the binary itself ships.
type Registry struct {
	mu sync.Mutex

	// kinds holds each kind's constructor rather than a kind, because a kind is
	// per run. See [Kind].
	kinds map[manifest.SourceKind]NewKind
}

// Default is the registry the kinds shipped with this binary register into, and
// the one the install flow resolves through. A kind package registers itself
// from its own init, so a kind that has been linked in is a kind that works.
var Default = &Registry{}

// Register adds a kind to [Default].
func Register(name manifest.SourceKind, newKind NewKind) {
	Default.Register(name, newKind)
}

// Register adds a kind under the name a manifest writes for it.
//
// A second registration of the same name panics rather than replacing or
// ignoring the first. Registration happens during package initialization, before
// the process has read anything, so the only way to reach it is a mistake in
// harnaas's own wiring — and the two silent outcomes are a binary that resolves
// through whichever kind happened to be linked last.
func (r *Registry) Register(name manifest.SourceKind, newKind NewKind) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if r.kinds == nil {
		r.kinds = make(map[manifest.SourceKind]NewKind)
	}
	if _, registered := r.kinds[name]; registered {
		panic(fmt.Sprintf("source: kind %q is registered twice", name))
	}
	r.kinds[name] = newKind
}

// Kinds returns every registered kind name, sorted.
//
// Sorted rather than in registration order, because registration order is
// whatever the import graph happens to produce and this list is rendered into
// the error a user reads when their kind is not among them.
func (r *Registry) Kinds() []manifest.SourceKind {
	r.mu.Lock()
	defer r.mu.Unlock()

	return r.kindNamesLocked()
}

// NewResolver constructs one resolver per registered kind and returns the
// [Resolver] that dispatches to them, which is the unit of one install run.
func (r *Registry) NewResolver() *Resolver {
	r.mu.Lock()
	defer r.mu.Unlock()

	kinds := make(map[manifest.SourceKind]Kind, len(r.kinds))
	for name, newKind := range r.kinds {
		kinds[name] = newKind()
	}
	return &Resolver{kinds: kinds, registered: r.kindNamesLocked()}
}

// kindNamesLocked returns the registered names in sorted order. The caller holds
// the lock.
func (r *Registry) kindNamesLocked() []manifest.SourceKind {
	names := make([]manifest.SourceKind, 0, len(r.kinds))
	for name := range r.kinds {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

// Resolver resolves every source of one install run.
//
// It holds one live kind per registered name, so the per-run state a kind keeps
// — chiefly which repository archives it has already fetched — lives exactly as
// long as the run that built it.
type Resolver struct {
	kinds map[manifest.SourceKind]Kind

	// registered is the sorted name list, captured at construction so the error
	// for an unsupported kind lists what this run could have resolved rather
	// than what the registry holds by the time somebody reads the message.
	registered []manifest.SourceKind
}

// Resolve resolves one asset's source through the kind that owns it.
//
// The lookup happens before the kind is asked to do anything, which is what
// makes "an unsupported kind reaches no network and writes no file" a property
// of the dispatch rather than a rule each kind has to honour on its way in.
func (r *Resolver) Resolve(ctx context.Context, req Request) (*Resolved, error) {
	name := req.Kind()

	kind, registered := r.kinds[name]
	if !registered {
		return nil, &UnsupportedKindError{Kind: name, Registered: slices.Clone(r.registered)}
	}

	return kind.Resolve(ctx, req)
}

// UnsupportedKindError reports a source kind no registered kind can resolve.
//
// The manifest layer rejects a kind its grammar does not know, so reaching this
// means a kind harnaas parses but this binary cannot fetch — an older binary
// meeting a manifest written for a newer one. That is why the remedy is an
// upgrade rather than an edit, and why the error is a type: the install flow
// attributes it to the asset that carried the source.
type UnsupportedKindError struct {
	// Kind is the unresolvable kind, exactly as the manifest wrote it.
	Kind manifest.SourceKind

	// Registered is every kind this binary can resolve, sorted.
	Registered []manifest.SourceKind
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *UnsupportedKindError) Error() string {
	names := make([]string, 0, len(e.Registered))
	for _, name := range e.Registered {
		names = append(names, string(name))
	}

	return fmt.Sprintf(
		"this harnaas cannot resolve sources of kind %q\n\n"+
			"Upgrade harnaas, or declare a source of a kind it installs: %s.",
		e.Kind, strings.Join(names, ", "),
	)
}

package source

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
)

// digestPrefix names the algorithm inside the value itself, so a digest recorded
// in the lockfile today stays readable by a binary that hashes differently
// tomorrow: it can tell "computed another way" from "the content changed", which
// a bare hex string could not.
const digestPrefix = "sha256:"

// Digest is a content digest, rendered as its algorithm and hexadecimal sum.
//
// It is a named type because harnaas stores digests beside paths, ids and refs
// in the lockfile, and a function taking one should not silently accept any of
// those. Comparison is the only operation: harnaas asks whether two digests are
// equal and never what they mean.
type Digest string

// DigestContent returns the digest of one file's bytes.
func DigestContent(content []byte) Digest {
	sum := sha256.Sum256(content)
	return Digest(digestPrefix + hex.EncodeToString(sum[:]))
}

// digestFiles returns the digest of a resolved source as a whole.
//
// Paths participate alongside content, so renaming a file changes the value even
// though no byte of it did — a source whose skill moved to a different file is a
// different source, and a digest that said otherwise would let `lint` report an
// unchanged install for content that no longer lands anywhere.
//
// File modes are not hashed at all. Harness assets are documents, an executable
// bit carries no meaning worth preserving, and hashing one would make the same
// content digest differently on platforms that report modes differently — which
// would turn a Windows machine and a Linux machine into a permanent disagreement
// about whether upstream had moved.
//
// The files must already be sorted by path, which [NewResolved] guarantees: the
// value has to be independent of archive order and of filesystem iteration
// order, and sorting at the one place a [Resolved] is built is what makes that a
// property of the type rather than a step each kind remembers.
func digestFiles(files []File) Digest {
	var canonical bytes.Buffer
	for _, file := range files {
		// The path is length-prefixed because it is untrusted input: an archive
		// entry may contain any byte, including the separators. Without a frame,
		// two different sets of files could serialize identically and hash the
		// same, which is the one failure a content digest may never have.
		fmt.Fprintf(&canonical, "%d %s %s\n", len(file.Path), file.Path, file.Digest)
	}
	return DigestContent(canonical.Bytes())
}

// Package source turns a declared source into content harnaas can install.
//
// The manifest layer parses a source and resolves nothing: `github:acme/assets@v1`
// is checked for shape, and whether that repository exists, whether the ref
// points anywhere and what is at the path are all questions it deliberately does
// not ask. This package answers them, and it is the only place in harnaas that
// reaches the network or reads content out of a repository.
//
// Two things shape it. Every source kind answers the same question — given a
// parsed source and a path within it, produce the files and the provenance
// needed to record what landed — so the kinds sit behind one contract and a
// [Registry] dispatches to them by name. And a resolved source is worthless
// unless it can be re-identified later: `lint` has to answer "did somebody edit
// this?" and "has upstream moved?" independently, months after the install, from
// nothing but what was recorded. That is why a [Resolved] carries a digest per
// file and one over the source as a whole, and why the only way to obtain one is
// a constructor that computes both.
package source

import (
	"context"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Kind resolves the sources of one kind for one install run.
//
// It is created per run rather than registered as a value, because resolution is
// not stateless: a repository archive is fetched at most once per repository and
// commit per run, and the memory of what has already been fetched belongs to the
// run that did it. A kind shared across runs would either leak that memory
// between them or need a global cache to hold it.
type Kind interface {
	// Resolve produces the content and provenance for one asset's source.
	//
	// It is handed one asset rather than one `sources` entry because the unit
	// being resolved is the subtree an asset names, and because every diagnostic
	// raised here has to name the asset the author would go and edit.
	Resolve(ctx context.Context, req Request) (*Resolved, error)
}

// NewKind constructs a kind's resolver for one install run. It is what a kind
// registers, for the reason [Kind] gives.
type NewKind func() Kind

// Request is one asset's resolution: the asset being resolved and the `sources`
// entry it references.
//
// The asset travels whole rather than as the two or three fields a kind reads,
// because the fields a diagnostic needs are not the fields resolution needs — a
// message names the asset's id and its position in the manifest, and narrowing
// the request would make every kind's errors worse to keep the struct smaller.
type Request struct {
	// Asset is the manifest entry being resolved, already interpreted: its
	// reference, type and id are settled before anything is fetched.
	Asset manifest.Asset

	// Source is the parsed `sources` entry the asset references. It is the zero
	// value for the project-local form, which references no entry.
	Source manifest.Source
}

// Kind reports which source kind must resolve this request.
//
// The project-local form declares no `sources` entry and is local by definition
// of the manifest grammar, not by anything a caller decides. Answering it here,
// once, is what keeps the install flow above and the kinds below from each
// restating that rule — and from restating it differently.
func (r Request) Kind() manifest.SourceKind {
	if r.Asset.Ref.Local() {
		return manifest.SourceKindLocal
	}
	return r.Source.Kind
}

// Package github resolves `github` sources: the ref a manifest pinned becomes
// the commit it names, and that commit's repository archive becomes the files
// an asset installs.
//
// Names are resolved with Git and bytes are moved over HTTPS, and the split is
// the whole design. `git ls-remote` goes through whatever credential helper the
// user already configured, so a private repository resolves without harnaas
// inventing an authentication story of its own, and that path has no API rate
// limit for a CI job to exhaust. The archive endpoint is then one request per
// repository and commit rather than one request per file, which is what makes a
// skill — a directory of documents — cost the same as a rule.
//
// Resolution is kept separate from retrieval for a second reason: the lockfile
// records what was *asked for* alongside what it *resolved to*, because "the
// installed files still match the commit" and "the tag now points somewhere
// else" are two different questions and `lint` asks them separately.
package github

// remoteHost is the forge this kind speaks to, and the only place its name is
// spelled: a message, a Git remote and an archive URL all read it from here, so
// they cannot come to disagree about which host a `github` source means.
const remoteHost = "github.com"

// remoteURL is the Git remote for an `owner/repository` pair.
//
// It is built rather than taken from the manifest, which is what keeps a
// declared source from naming a host harnaas never agreed to talk to. The
// repository arrives already checked for shape by the manifest grammar, so this
// is assembly and not validation.
func remoteURL(repository string) string {
	return "https://" + remoteHost + "/" + repository + ".git"
}

package github

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"context"
	"errors"
	"maps"
	"slices"
	"strings"
	"sync"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

const (
	// commitID is the commit every archive in this file is of, and the one the
	// tag below resolves to.
	commitID = "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba"

	// otherCommitID is a second commit in the same repository, which is what
	// makes "at most once per repository *and commit*" testable as more than
	// "at most once per repository".
	otherCommitID = "3d5b7e9012a4c6e8f0b2d4a6c8e02468ace13579"

	// wrapper is the top-level directory a forge puts around a repository
	// archive. Its spelling is the forge's to choose, which is why extraction
	// takes it from the archive rather than reconstructing it.
	wrapper = "acme-assets-9f2a1c4/"
)

// tagListing is what `ls-remote` prints for a repository whose tag v1.2.0 is a
// lightweight tag on commitID.
var tagListing = commitID + "\trefs/tags/v1.2.0\n"

// resolveRequest builds a request for one asset at a path within the source.
func resolveRequest(id, ref, path string) source.Request {
	req := request(ref)
	req.Asset.ID = id
	req.Asset.Ref = manifest.AssetRef{SourceKey: "acme", Path: path}
	return req
}

// archiveOf builds the gzipped tar a forge serves, wrapping every named file in
// the archive's single top-level directory.
func archiveOf(tb testing.TB, files map[string]string) []byte {
	tb.Helper()

	var buffer bytes.Buffer
	gz := gzip.NewWriter(&buffer)
	writer := tar.NewWriter(gz)

	for _, name := range slices.Sorted(maps.Keys(files)) {
		require.NoError(tb, writer.WriteHeader(&tar.Header{
			Name:     wrapper + name,
			Typeflag: tar.TypeReg,
			Size:     int64(len(files[name])),
			Mode:     0o644,
		}))
		_, err := writer.Write([]byte(files[name]))
		require.NoError(tb, err)
	}

	require.NoError(tb, writer.Close())
	require.NoError(tb, gz.Close())
	return buffer.Bytes()
}

// assetArchive is a plausible asset repository: two skills and a rule, so a
// declared subtree has both something to select and something to leave behind.
func assetArchive(tb testing.TB) []byte {
	tb.Helper()

	return archiveOf(tb, map[string]string{
		"README.md":                       "# assets",
		"skills/review/SKILL.md":          "review skill",
		"skills/review/reference/list.md": "checklist",
		"skills/release/SKILL.md":         "release skill",
		"rules/house-style.md":            "house style",
	})
}

// diagnostic is an error shaped the way the transport's own are: a problem, a
// blank line and a fix.
//
// It is a type rather than an errors.New value because revive refuses a message
// ending in punctuation — which is the same reason every diagnostic harnaas
// prints is a type with an Error method rather than a sentinel.
type diagnostic string

// Error renders the diagnostic as written.
func (d diagnostic) Error() string { return string(d) }

// countingFetcher answers every request with body and counts the URLs it was
// asked for, which is how "fetched at most once" is asserted as a number rather
// than inferred from a result that happens to be right.
type countingFetcher struct {
	mu          sync.Mutex
	urls        []string
	credentials []source.Credential
	body        []byte
	err         error
}

// fetch is the [archiveFetcher] the kind is built with.
func (f *countingFetcher) fetch(_ context.Context, url string, credential source.Credential) ([]byte, error) {
	f.mu.Lock()
	defer f.mu.Unlock()

	f.urls = append(f.urls, url)
	f.credentials = append(f.credentials, credential)
	if f.err != nil {
		return nil, f.err
	}
	return f.body, nil
}

// asked returns the URLs the kind fetched, in order.
func (f *countingFetcher) asked() []string {
	f.mu.Lock()
	defer f.mu.Unlock()

	return slices.Clone(f.urls)
}

// presented returns the credentials the kind fetched with, in the same order.
func (f *countingFetcher) presented() []source.Credential {
	f.mu.Lock()
	defer f.mu.Unlock()

	return slices.Clone(f.credentials)
}

func TestAnArchiveURLNamesTheCommitRatherThanTheRef(t *testing.T) {
	t.Parallel()

	got := archiveURL(repository, commitID)

	assert.Equal(t, "https://api.github.com/repos/acme/assets/tarball/"+commitID, got)
	assert.NotContains(t, got, "v1.2.0", "the ref has already been spent; the URL names an object that cannot move")
}

func TestResolveProducesTheSubtreeAndItsProvenance(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{body: assetArchive(t)}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{})

	resolved, err := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", "skills/review"))
	require.NoError(t, err)

	paths := make([]string, 0, len(resolved.Files))
	for _, file := range resolved.Files {
		paths = append(paths, file.Path)
	}
	assert.Equal(t, []string{"SKILL.md", "reference/list.md"}, paths)

	assert.Equal(t, source.Provenance{
		Kind:           manifest.SourceKindGitHub,
		Source:         "github:acme/assets@v1.2.0",
		RequestedRef:   "v1.2.0",
		ResolvedCommit: commitID,
	}, resolved.Provenance, "the ref asked for is recorded beside the commit it resolved to, never collapsed into it")
	assert.NotEmpty(t, resolved.Digest)
}

func TestABranchResolvesToAMutableSource(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{body: assetArchive(t)}
	kind := newKind(answeringRunner(commitID+"\trefs/heads/main\n", nil), fetcher.fetch, source.Credential{})

	resolved, err := kind.Resolve(t.Context(), resolveRequest("review", "main", "skills/review"))
	require.NoError(t, err)

	assert.True(t, resolved.Provenance.Mutable, "a branch can name something else tomorrow, and the lockfile has to say so")
}

func TestOneRepositoryAndCommitIsFetchedOncePerRun(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{body: assetArchive(t)}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{})

	for _, asset := range []struct{ id, path string }{
		{id: "review", path: "skills/review"},
		{id: "release", path: "skills/release"},
		{id: "house-style", path: "rules/house-style.md"},
	} {
		resolved, err := kind.Resolve(t.Context(), resolveRequest(asset.id, "v1.2.0", asset.path))
		require.NoError(t, err)
		assert.NotEmpty(t, resolved.Files, "every asset is extracted from the one archive")
	}

	assert.Len(t, fetcher.asked(), 1, "three assets in one repository at one commit share a single retrieval")
}

func TestASecondCommitIsItsOwnFetch(t *testing.T) {
	t.Parallel()

	archive := assetArchive(t)
	fetcher := &countingFetcher{body: archive}
	kind := newKind(func(_ context.Context, args ...string) ([]byte, error) {
		// The commit a ref resolves to is what keys the memo, so the two refs
		// here have to answer differently for the test to mean anything.
		if slices.Contains(args, "refs/tags/v1.3.0") {
			return []byte(otherCommitID + "\trefs/tags/v1.3.0\n"), nil
		}
		return []byte(tagListing), nil
	}, fetcher.fetch, source.Credential{})

	for _, ref := range []string{"v1.2.0", "v1.2.0", "v1.3.0"} {
		_, err := kind.Resolve(t.Context(), resolveRequest("review", ref, "skills/review"))
		require.NoError(t, err)
	}

	assert.Equal(t, []string{
		archiveURL(repository, commitID),
		archiveURL(repository, otherCommitID),
	}, fetcher.asked())
}

func TestConcurrentResolutionsStillFetchOnce(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{body: assetArchive(t)}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{})

	var group sync.WaitGroup
	for range 8 {
		group.Add(1)
		go func() {
			defer group.Done()

			_, err := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", "skills/review"))
			assert.NoError(t, err)
		}()
	}
	group.Wait()

	assert.Len(t, fetcher.asked(), 1)
}

func TestARetrievalFailureNamesTheAssetTheRepositoryAndTheCommit(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{err: diagnostic("could not fetch https://api.github.com/x: no such host\n\nCheck that this machine can reach the host.")}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{})

	resolved, err := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", "skills/review"))
	require.Nil(t, resolved, "a failed retrieval never resolves to content, empty or otherwise")

	var retrieval *ArchiveRetrievalError
	require.ErrorAs(t, err, &retrieval)
	assert.Equal(t, "review", retrieval.AssetID)
	assert.Equal(t, repository, retrieval.Repository)
	assert.Equal(t, commitID, retrieval.Commit)
}

func TestARememberedFailureNamesTheAssetThatMetIt(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{err: errors.New("the host refused")}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{})

	first, firstErr := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", "skills/review"))
	second, secondErr := kind.Resolve(t.Context(), resolveRequest("release", "v1.2.0", "skills/release"))

	require.Nil(t, first)
	require.Nil(t, second)
	assert.Len(t, fetcher.asked(), 1, "a repository that could not be fetched is not asked again for the next asset")
	assert.Contains(t, firstErr.Error(), `"review"`)
	assert.Contains(t, secondErr.Error(), `"release"`, "the remembered failure is attributed to the asset reading it")
}

func TestNoFailurePathResolvesToContent(t *testing.T) {
	t.Parallel()

	archive := assetArchive(t)

	cases := []struct {
		name    string
		listing string
		fetcher *countingFetcher
		path    string
	}{
		{
			name:    "unknown ref",
			fetcher: &countingFetcher{body: archive},
			path:    "skills/review",
		},
		{
			name:    "retrieval refused",
			listing: tagListing,
			fetcher: &countingFetcher{err: errors.New("the host refused")},
			path:    "skills/review",
		},
		{
			name:    "archive is not an archive",
			listing: tagListing,
			fetcher: &countingFetcher{body: []byte("<!doctype html>")},
			path:    "skills/review",
		},
		{
			name:    "path is not at the commit",
			listing: tagListing,
			fetcher: &countingFetcher{body: archive},
			path:    "skills/missing",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			kind := newKind(answeringRunner(tc.listing, nil), tc.fetcher.fetch, source.Credential{})

			resolved, err := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", tc.path))
			require.Error(t, err)
			assert.Nil(t, resolved, "no failure hands on a source, so none can converge to deleting what the asset installed")
			assert.Contains(t, err.Error(), "review", "every failure names the asset the author would go and edit")
		})
	}
}

func TestARetrievalFailureQuotesTheCausesProblemAndNotItsFix(t *testing.T) {
	t.Parallel()

	cause := diagnostic("example.invalid answered 404 Not Found\n\nCheck that the source the manifest declares exists.")
	err := &ArchiveRetrievalError{AssetID: "review", Repository: repository, Commit: commitID, Err: cause}

	message := err.Error()
	assert.Contains(t, message, "answered 404 Not Found")
	assert.NotContains(t, message, "Check that the source the manifest declares exists.",
		"one message offers one fix, or the reader has to decide which of two is theirs")
	assert.Equal(t, 1, strings.Count(message, "\n\n"), "problem, blank line, fix")
	require.ErrorIs(t, err, cause)
}

