	var canonical strings.Builder
	for _, field := range []string{string(key.Kind), key.Repository, key.Commit} {
		canonical.WriteString(strings.Repeat(" ", 0)) // no-op, kept out of the format below
		_, _ = canonical.WriteString(field)
	}
