// isHexSum reports whether s is a sha256 sum in hexadecimal, which is the only
// thing a pointer may contain and the only thing that may become part of a
// path.
func isHexSum(s string) bool {
	if len(s) != hexDigits {
		return false
	}
	for _, r := range s {
		switch {
		case r >= '0' && r <= '9', r >= 'a' && r <= 'f':
